#!/usr/bin/env bash
# Compiles src/data + src/player (pure Java parts) with test/ and runs every test class. Run in Git Bash from anywhere.
set -uo pipefail
cd "$(dirname "$0")/.."
[ -f local.env ] && { set -a; . ./local.env; set +a; }
AJ=$(cygpath -w "${ANDROID_SDK:-$(cygpath -u "${LOCALAPPDATA:-$HOME/AppData/Local}")/Android/Sdk}/platforms/android-36/android.jar")
OUT=build-test
rm -rf $OUT && mkdir -p $OUT/cfg/lk/manus/iptv
# Config is generated by build.sh; tests get a stub with the most restrictive (play) values
printf 'package lk.manus.iptv;\npublic final class Config { public static final boolean DEBUG = false, PLAY = %s, IPTVORG = %s; public static final String FEED_URL = ""; }\n' "${TEST_PLAY:-true}" "${TEST_IPTVORG:-false}" > $OUT/cfg/lk/manus/iptv/Config.java
javac -encoding UTF-8 -nowarn -d $OUT -cp "$AJ" $(find src/lk/manus/iptv/data src/lk/manus/iptv/player -name '*.java' | grep -v -E 'Media3Engine|MediaPlayerEngine|MiniPreview') src/lk/manus/iptv/ui/Ui.java $OUT/cfg/lk/manus/iptv/Config.java test/*.java 2>&1 | grep -v -E '^Note|warning' 
rc=0
for t in AudioTest DataLayerTest FavGuardTest GroupingTest HlsTest M3uParserTest NormalizerTest SearchTest SubTrTest WebVttTest; do
  echo "== $t"; java -cp $OUT "$t" test/sample.m3u 2>&1 | tail -3 || rc=1
done
rm -rf $OUT
exit $rc
